<?php require 'config.php';require_login();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$stmt=$pdo->prepare('SELECT * FROM tours WHERE id=? AND active=1');$stmt->execute([$id]);$tour=$stmt->fetch();if(!$tour){http_response_code(404);exit('Tour not found');}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$date=$_POST['tour_date']??'';$count=filter_var($_POST['visitors']??null,FILTER_VALIDATE_INT);$dt=DateTimeImmutable::createFromFormat('!Y-m-d',$date);if(!$dt||$dt->format('Y-m-d')!==$date||$date<date('Y-m-d')||!$count||$count<1||$count>10){$error='Choose a valid future date and 1–10 visitors.';}else{try{$pdo->beginTransaction();$lock=$pdo->prepare('SELECT * FROM tours WHERE id=? AND active=1 FOR UPDATE');$lock->execute([$id]);$locked=$lock->fetch();$used=$pdo->prepare('SELECT COALESCE(SUM(visitors),0) FROM bookings WHERE tour_id=? AND tour_date=? AND status=\'confirmed\'');$used->execute([$id,$date]);$seats=(int)$used->fetchColumn();if(!$locked||$seats+$count>(int)$locked['capacity']){$pdo->rollBack();$error='Not enough available seats on that date.';}else{$total=$count*(float)$locked['price'];$ins=$pdo->prepare('INSERT INTO bookings(user_id,tour_id,tour_date,visitors,total_price,status) VALUES(?,?,?,?,?,\'confirmed\')');$ins->execute([$_SESSION['uid'],$id,$date,$count,$total]);$pdo->commit();flash('Booking confirmed!');go('my_bookings.php');}}catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();$error='Booking failed. Please try again.';}}}require 'header.php';?><div class="formbox"><h1>Book a Tour</h1><p><strong><?=e($tour['title'])?></strong> — <?=e($tour['price'])?> SAR per visitor</p><?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Tour Date<input required type="date" min="<?=date('Y-m-d')?>" name="tour_date"></label><label>Number of Visitors<input required type="number" min="1" max="10" value="1" name="visitors"></label><p>Payment is not collected in this student demo.</p><button class="btn">Confirm Booking</button></form></div><?php require 'footer.php';?>